Problem:
A milk company is delivering milk to their local families’ homes directly either through bikes or by car. A worker on a bike can deliver 12 orders of milk and takes 40 minutes per trip. A worker on a car can deliver 50 orders of milk and takes 30 minutes per trip. The milk company needs to deliver at least 850 orders of milk. Additionally, at least 70% of delivery trips must be by bike to reduce the pollution. How many of each type of delivery trips must be scheduled to minimize the minutes per trip?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "bike delivery trips",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "car delivery trips",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "bike delivery trips",
     "coef": 40.0
    },
    {
     "var": "car delivery trips",
     "coef": 30.0
    }
   ]
  },
  "constraints": [
   {
    "name": "orders",
    "terms": [
     {
      "var": "bike delivery trips",
      "coef": 12.0
     },
     {
      "var": "car delivery trips",
      "coef": 50.0
     }
    ],
    "sense": ">=",
    "rhs": 850.0
   },
   {
    "name": "bike share",
    "terms": [
     {
      "var": "bike delivery trips",
      "coef": 0.3
     },
     {
      "var": "car delivery trips",
      "coef": -0.7
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 1370.0,
  "values": {
   "bike delivery trips": 26.0,
   "car delivery trips": 11.0
  },
  "binding": [],
  "slack": {
   "orders": 12.0,
   "bike share": 0.1
  },
  "shadow_prices": null
 }
}
